/**
 * AusbildungsWeg — UI dictionaries.
 *
 * German (`de`) is the source of truth and the default language. Every other
 * language is typed against `typeof de` so a missing/extra key is a compile
 * error — keeping all four languages structurally in sync without a build
 * step or an external i18n dependency.
 *
 * Only *interface* strings live here (navigation, buttons, labels, empty /
 * loading / error states, system messages). User-generated content — CVs,
 * AI responses, opportunity/company data, campaign text — is data and is
 * rendered verbatim, never routed through the dictionary.
 */

